def bounding_box(points):
    xs = [p[0] for p in points]
    ys = [p[1] for p in points]
    return (min(xs), min(ys), max(xs), max(ys))

def rectangles_overlap(r1, r2):
    x1a, y1a, x2a, y2a = r1
    x1b, y1b, x2b, y2b = r2
    if x2a <= x1b or x2b <= x1a:
        return False
    if y2a <= y1b or y2b <= y1a:
        return False
    return True

def point_in_triangle(p, a, b, c):
    def sign(p1, p2, p3):
        return (p1[0] - p3[0]) * (p2[1] - p3[1]) - (p2[0] - p3[0]) * (p1[1] - p3[1])
    d1 = sign(p, a, b)
    d2 = sign(p, b, c)
    d3 = sign(p, c, a)
    has_neg = (d1 < 0) or (d2 < 0) or (d3 < 0)
    has_pos = (d1 > 0) or (d2 > 0) or (d3 > 0)
    return not (has_neg and has_pos)

def are_collinear(p1, p2, p3):
    cross = (p2[0] - p1[0]) * (p3[1] - p1[1]) - (p2[1] - p1[1]) * (p3[0] - p1[0])
    return cross == 0

def classify_triangle_by_sides(p1, p2, p3):
    def d2(a, b):
        return (a[0] - b[0]) ** 2 + (a[1] - b[1]) ** 2
    ab = d2(p1, p2)
    bc = d2(p2, p3)
    ca = d2(p3, p1)
    if ab == bc == ca:
        return 'equilateral'
    if ab == bc or bc == ca or ca == ab:
        return 'isosceles'
    return 'scalene'

def is_point_on_segment(p, a, b):
    cross = (b[0] - a[0]) * (p[1] - a[1]) - (b[1] - a[1]) * (p[0] - a[0])
    if cross != 0:
        return False
    return min(a[0], b[0]) <= p[0] <= max(a[0], b[0]) and min(a[1], b[1]) <= p[1] <= max(a[1], b[1])

def count_points_in_rectangle(points, rect):
    x1, y1, x2, y2 = rect
    count = 0
    for (x, y) in points:
        if x1 <= x <= x2 and y1 <= y <= y2:
            count += 1
    return count

def count_points_in_circle(points, center, radius):
    cx, cy = center
    count = 0
    for (x, y) in points:
        dist2 = (x - cx) ** 2 + (y - cy) ** 2
        if dist2 <= radius ** 2:
            count += 1
    return count
